import urllib.request
import zipfile
import os
import urllib.error


def task_func(
    url: str,
    save_path: str = "downloaded_file.zip",
    extract_path: str = "extracted_files",
) -> str:
    try:
        if save_path:
            save_dir = os.path.dirname(save_path)
            if save_dir:
                os.makedirs(save_dir, exist_ok=True)
        os.makedirs(extract_path, exist_ok=True)
    except OSError as e:
        return f"Error: Failed to create required directory: {e}"

    try:
        with urllib.request.urlopen(url) as response, open(save_path, "wb") as out_file:
            while True:
                chunk = response.read(8192)
                if not chunk:
                    break
                out_file.write(chunk)
    except urllib.error.URLError as e:
        reason = getattr(e, "reason", e)
        return f"URL Error: {reason}"
    except OSError as e:
        return f"Error: Failed to save downloaded file: {e}"

    try:
        with zipfile.ZipFile(save_path, "r") as zip_ref:
            zip_ref.extractall(extract_path)
    except zipfile.BadZipFile:
        return "Error: Corrupted ZIP file"
    except OSError as e:
        return f"Error: Failed to extract ZIP file: {e}"

    try:
        os.remove(save_path)
    except OSError as e:
        return f"Error: Failed to delete downloaded ZIP file: {e}"

    return extract_path
